<main class="catalog-page"><div class="catalog-shell"><a class="catalog-back" href="<?= e(url('catalogue')) ?>">← Retour au catalogue</a><article class="product-detail"><div class="product-detail-visual"><?php if (! empty($product['images'])): ?><img src="<?= e(url('produit-image/' . $product['images'][0]['id'])) ?>" alt="<?= e($product['images'][0]['alt_text'] ?: $product['name']) ?>"><?php else: ?><span><?= e(substr($product['name'], 0, 1)) ?></span><?php endif; ?></div><div><span class="catalog-kicker"><?= e($product['category_name']) ?></span><h1><?= e($product['name']) ?></h1><p class="product-detail-lead"><?= e($product['short_description'] ?? '') ?></p><?php if ($product['brand_name']): ?><p>Marque : <?= e($product['brand_name']) ?></p><?php endif; ?><?php if (! empty($product['ingredients'])): ?><p>Principes actifs : <?= e(implode(', ', array_column($product['ingredients'], 'name'))) ?></p><?php endif; ?><?php if ((int) $product['requires_prescription'] === 1): ?><div class="prescription-notice">Ce produit necessite une ordonnance. Elle sera demandee avant la validation de la commande.</div><?php endif; ?><p><?= e($product['description'] ?? 'Les informations detaillees seront completees par le catalogue medical.') ?></p><?php if (! empty($product['variants'])): ?><h2>Variantes</h2><ul><?php foreach ($product['variants'] as $variant): ?><li><?= e($variant['name']) ?><?= $variant['sku'] ? ' · ' . e($variant['sku']) : '' ?></li><?php endforeach; ?></ul><?php endif; ?><a class="catalog-cart" href="<?= e(url('panier')) ?>">Ajouter au panier</a></div></article></div></main>